{
  "name": "SyncConflict",
  "type": "object",
  "properties": {
    "conflict_key": {
      "type": "string"
    },
    "dataset": {
      "type": "string",
      "enum": [
        "sales",
        "orders"
      ]
    },
    "entity_id": {
      "type": "string"
    },
    "record_label": {
      "type": "string"
    },
    "field_name": {
      "type": "string"
    },
    "field_label": {
      "type": "string"
    },
    "sheet_id": {
      "type": "string"
    },
    "row_id": {
      "type": "string"
    },
    "column_id": {
      "type": "string"
    },
    "local_value": {
      "type": "string"
    },
    "remote_value": {
      "type": "string"
    },
    "baseline_value": {
      "type": "string"
    },
    "local_modified_at": {
      "type": "string"
    },
    "remote_modified_at": {
      "type": "string"
    },
    "local_version": {
      "type": "string"
    },
    "remote_version": {
      "type": "string"
    },
    "reason": {
      "type": "string"
    },
    "status": {
      "type": "string",
      "enum": [
        "open",
        "approved",
        "resolved",
        "superseded"
      ]
    },
    "decision": {
      "type": "string",
      "enum": [
        "app",
        "smartsheet"
      ]
    },
    "resolved_by": {
      "type": "string"
    },
    "resolved_at": {
      "type": "string"
    }
  },
  "required": [
    "conflict_key",
    "dataset",
    "entity_id",
    "field_name",
    "status"
  ],
  "rls": {
    "create": { "user_condition": { "role": "__syncconflict_backend_only__" } },
    "read": { "user_condition": { "role": "__syncconflict_backend_only__" } },
    "update": { "user_condition": { "role": "__syncconflict_backend_only__" } },
    "delete": { "user_condition": { "role": "__syncconflict_backend_only__" } }
  }
}

{
  "type": "object",
  "name": "TaskTemplate",
  "properties": {
    "name": {
      "type": "string",
      "description": "Template name"
    },
    "tasks": {
      "type": "array",
      "description": "List of task texts",
      "default": [],
      "items": {
        "type": "object",
        "properties": {
          "text": {
            "type": "string"
          },
          "sub_tasks": {
            "type": "array",
            "default": [],
            "items": {
              "type": "object",
              "properties": {
                "text": {
                  "type": "string"
                },
                "details": {
                  "type": "array",
                  "default": [],
                  "items": {
                    "type": "string"
                  }
                }
              }
            }
          }
        }
      }
    }
  },
  "required": [
    "name",
    "tasks"
  ]
,
  "rls": {
    "create": { "user_condition": { "role": "__tasktemplate_backend_only__" } },
    "read": { "user_condition": { "role": "__tasktemplate_backend_only__" } },
    "update": { "user_condition": { "role": "__tasktemplate_backend_only__" } },
    "delete": { "user_condition": { "role": "__tasktemplate_backend_only__" } }
  }
}

{
  "name": "TaxAgency",
  "type": "object",
  "description": "Tax agency registry: one row per taxing authority the shop remits to (state, county, city, or special district). TaxGroup rows optionally reference an agency via agency_id so collected tax can be reported and remitted per jurisdiction.",
  "properties": {
    "name": {
      "type": "string",
      "description": "Agency label, e.g. 'Ohio Dept. of Taxation' or 'Hamilton County'."
    },
    "rate": {
      "type": "number",
      "description": "Tax rate this agency levies, as a percent (e.g. 7.8 for 7.8%)."
    },
    "jurisdiction": {
      "type": "string",
      "description": "Geographic/political jurisdiction the agency covers, e.g. 'Ohio', 'Hamilton County', 'Cincinnati'."
    },
    "gl_account": {
      "type": "string",
      "description": "General-ledger liability account code/name that collected tax for this agency posts to."
    },
    "reporting_period": {
      "type": "string",
      "description": "Filing cadence for remittance, e.g. 'monthly', 'quarterly', 'annual'. Stored free-form so shop-specific periods are allowed."
    },
    "status": {
      "type": "string",
      "description": "Lifecycle status, e.g. 'active' or 'inactive'. Inactive agencies are hidden from new tax-group assignments."
    }
  },
  "rls": {
    "create": {
      "user_condition": {
        "role": "__taxagency_backend_only__"
      }
    },
    "read": {
      "user_condition": {
        "role": "__taxagency_backend_only__"
      }
    },
    "update": {
      "user_condition": {
        "role": "__taxagency_backend_only__"
      }
    },
    "delete": {
      "user_condition": {
        "role": "__taxagency_backend_only__"
      }
    }
  }
}

{
  "name": "TaxGroup",
  "type": "object",
  "description": "Sales tax group selectable on an estimate (e.g. 'Ohio - Hamilton County (7.8%)'). Picking a tax group sets the estimate's tax_percent, which the All-In-One pricing waterfall multiplies by the taxable base. Admin-managed on the Estimate Settings page.",
  "properties": {
    "group_name": {
      "type": "string"
    },
    "tax_percent": {
      "type": "number",
      "default": 0
    },
    "is_default": {
      "type": "boolean",
      "default": false
    },
    "is_active": {
      "type": "boolean",
      "default": true
    },
    "sort_order": {
      "type": "number",
      "default": 0
    },
    "agency_id": {
      "type": "string",
      "description": "Optional reference to a TaxAgency record \u2014 the taxing authority this group's collected tax is remitted/reported to."
    }
  },
  "required": [
    "group_name"
  ],
  "rls": {
    "create": {
      "user_condition": {
        "role": "__taxgroup_backend_only__"
      }
    },
    "read": {
      "user_condition": {
        "role": "__taxgroup_backend_only__"
      }
    },
    "update": {
      "user_condition": {
        "role": "__taxgroup_backend_only__"
      }
    },
    "delete": {
      "user_condition": {
        "role": "__taxgroup_backend_only__"
      }
    }
  }
}

