{
  "name": "TimeClockAdminCorrectionGate",
  "type": "object",
  "properties": {
    "scope": {
      "type": "string",
      "enum": [
        "company"
      ],
      "description": "Exactly one backend-provisioned company coordinator. Missing/duplicate rows block manager corrections."
    },
    "status": {
      "type": "string",
      "enum": [
        "idle",
        "creating"
      ],
      "description": "Backend-only company-wide manager correction CAS status."
    },
    "request_id": {
      "type": "string"
    },
    "time_entry_id": {
      "type": "string"
    },
    "payload_hash": {
      "type": "string"
    },
    "claim_token": {
      "type": "string"
    },
    "started_at": {
      "type": "string",
      "format": "date-time"
    }
  },
  "required": [
    "scope",
    "status"
  ],
  "rls": {
    "create": {
      "user_condition": {
        "role": "timeclock_backend_only"
      }
    },
    "read": {
      "user_condition": {
        "role": "timeclock_backend_only"
      }
    },
    "update": {
      "user_condition": {
        "role": "timeclock_backend_only"
      }
    },
    "delete": {
      "user_condition": {
        "role": "timeclock_backend_only"
      }
    }
  }
}

{
  "name": "TimeClockAdminNote",
  "type": "object",
  "properties": {
    "request_id": {
      "type": "string",
      "description": "Idempotency key for the employee's note submission"
    },
    "user_email": {
      "type": "string",
      "description": "Employee who sent the note"
    },
    "user_name": {
      "type": "string",
      "description": "Employee display name snapshot"
    },
    "note": {
      "type": "string",
      "description": "Employee note text for administrators"
    },
    "status": {
      "type": "string",
      "enum": [
        "new",
        "acknowledged"
      ],
      "default": "new",
      "description": "Admin-facing read state"
    },
    "requested_at": {
      "type": "string",
      "format": "date-time",
      "description": "Trusted backend timestamp when the note was submitted"
    },
    "acknowledged_by": {
      "type": "string",
      "description": "Administrator email that acknowledged the note"
    },
    "acknowledged_at": {
      "type": "string",
      "format": "date-time",
      "description": "Trusted backend timestamp of acknowledgement"
    },
    "resolution_note": {
      "type": "string",
      "description": "Optional admin reply/context stored with acknowledgement"
    }
  },
  "required": [
    "user_email",
    "request_id",
    "note",
    "status",
    "requested_at"
  ],
  "rls": {
    "create": {
      "user_condition": {
        "role": "timeclock_backend_only"
      }
    },
    "read": {
      "user_condition": {
        "role": "timeclock_backend_only"
      }
    },
    "update": {
      "user_condition": {
        "role": "timeclock_backend_only"
      }
    },
    "delete": {
      "user_condition": {
        "role": "timeclock_backend_only"
      }
    }
  }
}

{
  "name": "TimeClockAudit",
  "type": "object",
  "properties": {
    "action": {
      "type": "string",
      "enum": [
        "clock_in",
        "clock_out",
        "state_recovery",
        "admin_correction",
        "admin_archive",
        "notes_update",
        "delete",
        "reset",
        "badge_issue",
        "badge_rotate",
        "correction_request",
        "correction_review",
        "break_start",
        "break_end",
        "work_pause_start",
        "work_pause_resume",
        "work_pause_report_missed",
        "time_approval",
        "pay_period_create",
        "pay_period_status",
        "labor_start",
        "labor_change",
        "labor_stop",
        "time_off_request_create",
        "time_off_request_update",
        "pto_balance_assign",
        "pto_policy_delete",
        "pto_policy_update",
        "pto_policy_create",
        "punch_exception"
      ]
    },
    "outcome": {
      "type": "string",
      "enum": [
        "pending",
        "confirmed",
        "reused",
        "blocked",
        "recovered"
      ]
    },
    "user_email": {
      "type": "string"
    },
    "user_name": {
      "type": "string"
    },
    "actor_email": {
      "type": "string"
    },
    "actor_role": {
      "type": "string"
    },
    "authentication_method": {
      "type": "string",
      "enum": [
        "session",
        "admin_kiosk",
        "badge",
        "system"
      ]
    },
    "server_timestamp": {
      "type": "string",
      "format": "date-time"
    },
    "request_id": {
      "type": "string"
    },
    "time_entry_id": {
      "type": "string"
    },
    "reason": {
      "type": "string"
    },
    "details": {
      "type": "object"
    }
  },
  "required": [
    "action",
    "outcome",
    "user_email",
    "server_timestamp"
  ],
  "rls": {
    "create": {
      "user_condition": {
        "role": "timeclock_backend_only"
      }
    },
    "read": {
      "$or": [
        {
          "data.user_email": "{{user.email}}"
        },
        {
          "user_condition": {
            "role": "admin"
          }
        }
      ]
    },
    "update": {
      "user_condition": {
        "role": "timeclock_backend_only"
      }
    },
    "delete": {
      "user_condition": {
        "role": "timeclock_backend_only"
      }
    }
  }
}

{
  "name": "TimeClockBadge",
  "type": "object",
  "properties": {
    "user_email": {
      "type": "string",
      "description": "Employee email for this Time Clock badge"
    },
    "token_hash": {
      "type": "string",
      "description": "SHA-256 hash of the badge bearer secret; raw token is never stored"
    },
    "badge_version": {
      "type": "number",
      "default": 1
    },
    "issued_at": {
      "type": "string",
      "format": "date-time"
    },
    "revoked_at": {
      "type": "string",
      "format": "date-time"
    },
    "last_used_at": {
      "type": "string",
      "format": "date-time"
    }
  },
  "required": [
    "user_email",
    "token_hash",
    "badge_version",
    "issued_at"
  ],
  "rls": {
    "create": {
      "user_condition": {
        "role": "timeclock_backend_only"
      }
    },
    "read": {
      "user_condition": {
        "role": "admin"
      }
    },
    "update": {
      "user_condition": {
        "role": "timeclock_backend_only"
      }
    },
    "delete": {
      "user_condition": {
        "role": "timeclock_backend_only"
      }
    }
  }
}

{
  "name": "TimeClockBreak",
  "type": "object",
  "properties": {
    "user_email": {
      "type": "string",
      "description": "Employee email for this break"
    },
    "user_name": {
      "type": "string",
      "description": "Employee display name snapshot"
    },
    "time_entry_id": {
      "type": "string",
      "description": "Active TimeEntry this break belongs to"
    },
    "break_type": {
      "type": "string",
      "enum": [
        "lunch",
        "break",
        "other"
      ],
      "description": "Employee-selected break category"
    },
    "is_paid": {
      "type": "boolean",
      "description": "Whether this break remains paid/worked time"
    },
    "started_at": {
      "type": "string",
      "format": "date-time",
      "description": "Trusted backend break-start timestamp"
    },
    "ended_at": {
      "type": "string",
      "format": "date-time",
      "description": "Trusted backend break-end timestamp"
    },
    "duration_minutes": {
      "type": "number",
      "description": "Completed break duration in whole minutes"
    },
    "status": {
      "type": "string",
      "enum": [
        "active",
        "completed"
      ],
      "default": "active"
    },
    "start_request_id": {
      "type": "string",
      "description": "Idempotency request id for break start"
    },
    "end_request_id": {
      "type": "string",
      "description": "Idempotency request id for break end"
    },
    "source": {
      "type": "string",
      "enum": [
        "server",
        "admin_correction"
      ],
      "default": "server"
    }
  },
  "required": [
    "user_email",
    "time_entry_id",
    "break_type",
    "is_paid",
    "started_at",
    "status"
  ],
  "rls": {
    "create": {
      "user_condition": {
        "role": "timeclock_backend_only"
      }
    },
    "read": {
      "$or": [
        {
          "data.user_email": "{{user.email}}"
        },
        {
          "user_condition": {
            "role": "admin"
          }
        }
      ]
    },
    "update": {
      "user_condition": {
        "role": "timeclock_backend_only"
      }
    },
    "delete": {
      "user_condition": {
        "role": "timeclock_backend_only"
      }
    }
  }
}

{
  "name": "TimeClockCorrectionRequest",
  "type": "object",
  "properties": {
    "user_email": {
      "type": "string",
      "description": "Employee who owns the TimeEntry and submitted the correction request"
    },
    "user_name": {
      "type": "string",
      "description": "Employee display name snapshot"
    },
    "time_entry_id": {
      "type": "string",
      "description": "TimeEntry being disputed/corrected"
    },
    "time_entry_updated_date": {
      "type": "string",
      "description": "TimeEntry version observed when the employee submitted the request"
    },
    "request_id": {
      "type": "string",
      "description": "Idempotency key for employee submission"
    },
    "requested_at": {
      "type": "string",
      "format": "date-time",
      "description": "Trusted backend timestamp when submitted"
    },
    "attachment_url": {
      "type": "string",
      "description": "Optional photo/document URL attached to the correction (paper slip scan)"
    },
    "employee_reason": {
      "type": "string",
      "description": "Employee explanation for the requested correction"
    },
    "original_snapshot": {
      "type": "object",
      "description": "Immutable snapshot of the TimeEntry at request time"
    },
    "requested_changes": {
      "type": "object",
      "description": "Employee-requested punch/lunch/notes values"
    },
    "status": {
      "type": "string",
      "enum": [
        "pending",
        "reviewing",
        "approved",
        "approved_modified",
        "rejected",
        "cancelled"
      ],
      "default": "pending"
    },
    "review_started_at": {
      "type": "string",
      "format": "date-time",
      "description": "Trusted backend timestamp when a manager claimed the request for review"
    },
    "reviewed_at": {
      "type": "string",
      "format": "date-time",
      "description": "Trusted backend timestamp of manager decision"
    },
    "reviewer_email": {
      "type": "string",
      "description": "Administrator who reviewed the request"
    },
    "reviewer_reason": {
      "type": "string",
      "description": "Manager review note/reason"
    },
    "applied_audit_id": {
      "type": "string",
      "description": "TimeClockAudit record that applied the approved correction"
    },
    "review_request_id": {
      "type": "string",
      "description": "Idempotency key for manager decision"
    },
    "review_decision": {
      "type": "string",
      "enum": [
        "approve",
        "approve_modified",
        "reject"
      ],
      "description": "Manager decision bound to review_request_id"
    },
    "review_payload_hash": {
      "type": "string",
      "description": "SHA-256 fingerprint binding the manager decision, reason, and edited correction payload to review_request_id"
    },
    "request_kind": {
      "type": "string",
      "enum": [
        "standard",
        "missed_clock_out"
      ],
      "default": "standard",
      "description": "Correction workflow source; missed_clock_out is created from stale-shift recovery"
    },
    "punch_exception_id": {
      "type": "string",
      "description": "TimeClockPunchException that created this correction request, when applicable"
    }
  },
  "required": [
    "user_email",
    "time_entry_id",
    "request_id",
    "requested_at",
    "employee_reason",
    "original_snapshot",
    "requested_changes",
    "status"
  ],
  "rls": {
    "create": {
      "user_condition": {
        "role": "timeclock_backend_only"
      }
    },
    "read": {
      "$or": [
        {
          "data.user_email": "{{user.email}}"
        },
        {
          "user_condition": {
            "role": "admin"
          }
        }
      ]
    },
    "update": {
      "user_condition": {
        "role": "timeclock_backend_only"
      }
    },
    "delete": {
      "user_condition": {
        "role": "timeclock_backend_only"
      }
    }
  }
}

{
  "type": "object",
  "name": "TimeClockDevice",
  "properties": {
    "device_name": {
      "type": "string",
      "description": "Display name for the kiosk device (Front Lobby Kiosk, Shop Tablet 2)"
    },
    "device_key": {
      "type": "string",
      "description": "Stable identifier stored in localStorage on the kiosk (kiosk_device_id)"
    },
    "device_type": {
      "type": "string",
      "enum": [
        "kiosk",
        "tablet",
        "desktop",
        "mobile",
        "scanner"
      ],
      "default": "kiosk"
    },
    "location": {
      "type": "string",
      "description": "Physical placement - Front entrance, Shop floor, Warehouse"
    },
    "ip_address": {
      "type": "string"
    },
    "last_seen_at": {
      "type": "string",
      "description": "Updated whenever the kiosk registers or punches",
      "format": "date-time"
    },
    "firmware_version": {
      "type": "string",
      "description": "Reported app/agent version for offline-update tracking"
    },
    "status": {
      "type": "string",
      "enum": [
        "active",
        "provisioning",
        "offline",
        "retired"
      ],
      "default": "active"
    },
    "is_active": {
      "type": "boolean",
      "default": true
    },
    "provisioned_at": {
      "type": "string",
      "format": "date-time"
    },
    "provisioned_by_email": {
      "type": "string"
    },
    "archived_test_data": {
      "type": "boolean",
      "default": false
    }
  },
  "required": [
    "device_key"
  ],
  "rls": {
